def sync_from_steemd():
    b = Blockchain()
    h = b.stream_from(
        start_block=db_last_block() + 1,
        full_blocks=True,
    )
    buffer = [] # TODO: only needed during resync
    for block in h:
        buffer.append(block)
        if len(buffer) == 250:
            process_blocks(buffer)
            buffer = []
    process_blocks(buffer)

